// Final skill model (PvP V1 roster, 03_FINAL_CLASS_SKILL_ROSTER.md). Gameplay data only — art never drives damage.

export type ClassId = 'warrior' | 'book_mage' | 'archer' | 'samurai' | 'gambler';
export type Targeting =
  | 'aimAssist' // basic: facing snapped toward the mouse when it is near
  | 'mouseDir' // dash / directional action toward the mouse
  | 'mouseProjectile'
  | 'mouseLine'
  | 'mouseCone'
  | 'mouseGround'
  | 'mouseTarget' // first legal target in an aim corridor
  | 'self'
  | 'selfAim'; // self-centred, biased toward the aim
export type Role =
  | 'basic' | 'opener' | 'gapClose' | 'launcher' | 'extender' | 'airExtender' | 'knockdown' | 'antiAir' | 'confirm' | 'peel'
  | 'setup' | 'hardCC' | 'zone' | 'pull' | 'projectile' | 'precision' | 'trap' | 'mobility' | 'chase' | 'counter' | 'escape'
  | 'finisher' | 'signature' | 'ultimate';
export type CoverMode = 'BLOCKED_BY_COVER' | 'EXPLODES_ON_COVER' | 'PIERCES_ACTORS' | 'ARCS_OVER_LOW_COVER' | 'IGNORES_COVER';

/** Shape of one hit, evaluated relative to the cast origin/aim (or a placed point). World units = map px. */
export type HitShape =
  | { kind: 'sector'; range: number; angle: number; offset?: number }
  | { kind: 'circle'; radius: number; at?: 'self' | 'place' | 'aimBias'; bias?: number; /** strikes the floor below an airborne caster */ floor?: boolean }
  | { kind: 'line'; length: number; width: number }
  | { kind: 'capsule'; radius: number } // swept along the caster's dash path
  | { kind: 'projectile'; speed: number; range: number; radius: number; count?: number; spread?: number; /** parallel rows across the floor's depth */ rows?: number; rowGap?: number; pierce?: boolean; explodeRadius?: number; arc?: number; /** turns toward a foe (deg/s): each shot of a fan picks its own foe */ homing?: number; /** aimed up at a foe in the air in front (rises to his body as it flies): air combos */ antiAir?: boolean;
    /** The Shuriken Assassin's big star (Return Edge): one real object out of his hand — it waits `park` ms at the end of its
     *  flight (or where cover stopped it), then flies home to his hand at `speed` px/s, cutting what it crosses again on the
     *  way (`back` of the hit's damage, a `stun` ms flinch that never holds a foe in the air up). One star a caster: a throw
     *  while it is out sends it on from where it is. */
    edge?: EdgeSpec }
  | { kind: 'chain'; corridor: number; width: number; jump: number }
  | { kind: 'placed'; radius: number }; // ground point (rune / trap / zone)

/** The big star's way out and home (HitShape projectile `edge`). */
export interface EdgeSpec { park: number; speed: number; back: number; stun: number }

export interface Reaction {
  /** A foe in the air is not held up by it (he keeps falling): streams and pokes that should not juggle. */
  drop?: boolean;
  /** Caught near the floor (falling, landing or lying): stood up at once and held — the combo goes on (a trap on the floor). */
  catch?: boolean;
  /** Yanked to the attacker, stopping this far from him (a vine whip): even out of the air — the combo comes back in reach. */
  yank?: number;
  /** Ordinary combo hit-stun (soft, repeatable, scaled by combo index). */
  stun?: number;
  /** Knockback distance (world px, away from the hit origin). */
  push?: number;
  /** Pull toward the hit centre (px). */
  pull?: number;
  /** Drawn across the floor's depth toward the attacker's line, at most this far (px): into the middle lane (Twin
   *  Traverse, Crosslane Split). */
  lane?: number;
  /** Launch apex above the victim's current height (px). */
  launch?: number;
  /** Airborne victim: slam down (ground breaker) / stabilise for follow-ups. */
  slam?: boolean;
  float?: boolean;
  knockdown?: 'light' | 'heavy';
  /** Hard crowd control (shared DR policy). */
  /** After a launch's top, the body sinks slowly for this long (ms from the hit): Astral Lift's tube of light lowers him. */
  slowFall?: number;
  /** A pull's length (ms, default 110): Judgment Hook's chain draws him in so it reads. */
  pullMs?: number;
  /** A knockdown driven high and far (a drive: Grand Slam): its throw's rise (px/s) and distance (px), in place of THROWN's. */
  fly?: { vz: number; dist: number };
  /** An air hold's height (px, default GAUGE.holdCeil): the body is held up toward it (Call the Deck: well above its card). */
  holdZ?: number;
  hardCC?: { kind: 'root' | 'freeze' | 'stun'; ms: number; /** a binding skill: its full duration holds (not capped like a hit's root) */ long?: boolean };
  slow?: { pct: number; ms: number };
  juggleCost?: number;
  /** Pin the victim in place (no gravity, no drift) for this long (ms). */
  pin?: number;
  /** Grab: ignores the combo-protection gauges. */
  grab?: boolean;
  /** Warrior Judgment court: a foe on (or just over) the floor is chained upright in place for this long (ms) — the floor
   *  phase becomes a standing one again (once per combo: the court's catch, then the beating, then the next launch). */
  bind?: number;
  /** Book Mage Paper Curse: folded into a paper crane (ms): moves slowly, cannot attack; a heavy hit unfolds it. */
  curse?: number;
  /** Book Mage Levity Field: gravity turns over (ms): the body floats up and hangs there, unable to move. */
  levity?: number;
  /** A shove into a real wall (a prop, the room's edge): he crashes into it and comes off it, bouncing once off the floor
   *  (WALL CRASH) — off a standing shove too, not only a drive (`fly`). The Siege Warden's Rivet Drive. */
  wall?: boolean;
}

export interface HitEvent {
  /** ms after the active start. */
  at: number;
  damage: number;
  shape: HitShape;
  reaction: Reaction;
  /** Vertical reach above the attacker's feet (melee), px. */
  reachUp?: number;
  /** The arena: how far off the attack's line (in floor depth) it still hits, px (+ the target's own radius). */
  depth?: number;
  heavy?: boolean;
  /** Book Mage element: frost chills (a second chill freezes), storm conducts through chilled foes, both = both. */
  el?: 'frost' | 'storm' | 'both';
  /** Book Mage caster passives carried by the hit: Shatter Mastery's shatter multiplier, Conductor. */
  shatterMul?: number;
  conductor?: boolean;
  /** Archer: Hunter's Mark stacks this hit leaves on the foe (max 3, 6s). */
  mark?: number;
  /** Archer: this hit spends the foe's marks for its bonus (launch higher / double blast / paralyse / roar damage). */
  useMark?: 'launch' | 'blast' | 'stun' | 'roar';
  /** Gambler: charged cards this hit leaves stuck in the foe (they burst a beat later; max 5). */
  stick?: number;
  /** Gambler: a staff blow — it sets off the cards stuck in the foe at once (Short Fuse). */
  fuse?: boolean;
  /** Archer: a shot that crossed Thunder Rain's charged floor and came out as lightning — on its hit a bolt chains to the
   *  nearest other foe (the scene). Set by the runtime on the shot's hit, never in the kit. */
  storm?: boolean;
  /** The blow that ends its skill (its last hit; a chain's: its last stage's last) — the foe is sent back on it
   *  (Combat: THROWN). Set once at load (FinalKit), never in the kit; the re-timed copies carry it. */
  lastBlow?: boolean;
  /** The Shuriken Assassin: this hit calls his big star home instead of throwing it — a star of his out turns for his hand
   *  at once (at `speed`; `loft` px of arc over its line: Rising Return, Returning Moon), its way home carrying this hit; none
   *  out: it is thrown (the hit's own shape) and comes home at once. */
  recall?: { speed?: number; loft?: number };
  /** The big star's light cut on its own way home (EdgeSpec `back`). Set by the runtime, never in the kit. */
  edgeBack?: boolean;
  /** The Fulminant Conductor's Polarity (StyleMechanics POLARITY): a + strike marks the foe, a − strike snaps the mark. */
  pol?: 1 | -1;
  /** The Sailwright's Tack (StyleMechanics TACK): this hit leaves a pale-mint chevron on the foe. */
  tack?: boolean;
}

export interface FinalSkill {
  id: string;
  cls: ClassId;
  slot: number; // 0 = Space
  name: string;
  roles: Role[];
  targeting: Targeting;
  startup: number;
  active: number;
  recovery: number;
  cooldown: number;
  ground: boolean;
  air: boolean;
  hits: HitEvent[];
  /** Basic chains: stage list (Space repeats cycle stages; reset after `chainResetMs`). */
  chain?: { stages: HitEvent[][]; resetMs: number; timings?: { startup: number; active: number; recovery: number }[] };
  cover: CoverMode;
  /** Locomotion scalar while the action runs (0 = locked). */
  move: { startup: number; active: number; recovery: number };
  /** Dash / leap of the caster during active (px, toward aim). */
  dash?: { distance: number; lift?: number; /** rise fast, hold at the top, drop at the end (shots from the apex) */ hang?: boolean; stopOnHit?: boolean; /** arc back down to the ground by the end of active (leap attacks) */ crash?: boolean; /** locked on a foe: it stops this far short of him (px, centre to centre; default 34 — body to body) */ gap?: number };
  /** Ranged placement limit for ground target skills. */
  placeRange?: number;
  /** Ground target: opened under the nearest foe in placeRange (any side), not at the aim's distance (a catch under him). */
  snapPlace?: boolean;
  /** A floor bomb (the Cannoneer's): lands under the nearest foe in front inside placeRange — in the arena too (where a
   *  snapPlace is not snapped) — else ahead at the aim's distance. */
  seekFoe?: boolean;
  /** The Shuriken Assassin: the skill throws his big star itself (its own flight is its look) — a star of his still out is
   *  back in his hand at once when it starts (one star). */
  takesStar?: boolean;
  /** Persistent zone / trap lifetime after active (ms). */
  zoneMs?: number;
  /** Detached lingering hits (cracks / summons): keep striking after the caster moves on or cancels. */
  linger?: { at: 'origin' | 'aim' | 'caster' | 'place' | 'target'; offset?: number; startMs: number; everyMs: number; count: number; radius: number; maxZ: number; hit: HitEvent;
    /** ('target': a hold under the foe the cast's first landed hit struck — it follows him wherever he is thrown and
     *  strikes only him, at his own height (radius / maxZ unused); it starts `startMs` after that hit; a cast's
     *  `holdCount` sets its turns. Drawn by the class's `holdTick` and its 3D recipe's `tick`.) The last turn's hit. */ last?: HitEvent;
    /** each foe is struck by it once (a trap on the floor that catches whoever lands on it) */ once?: boolean;
    /** foes the cast's own hits already struck are left to them (the trap only takes the ones that fall into it later) */ fresh?: boolean;
    /** a band along the aim from the origin instead of a circle */ line?: { length: number; width: number } };
  /** Dash passes through bodies and turns to face the target behind. */
  through?: boolean;
  /** Uses in a row before the full cooldown. */
  charges?: number;
  /** Minimum gap between two charges (ms, from cast to cast); default 350. */
  chargeGap?: number;
  /** Hold-to-charge: the key held keeps the startup going (up to `startup`, at least minMs); at the release the level whose
   *  `at` the startup reached picks the hits (both sides pick it from the startup: the release is sent to the others). */
  charge?: { minMs: number; levels: { at: number; hits: HitEvent[] }[] };
  /** A priming stance (the samurai's Sheathe): the caster's next cast, if it is one of `ids` and starts within `windowMs`
   *  of the stance's end, has no startup — a hold-to-charge skill `chargeUp` levels higher. Any other cast spends it. */
  primes?: { ids: string[]; windowMs: number; chargeUp?: number; /** the primed skill's wind-up shorter by this (real ms) instead of none (the Sniper's Steady Chamber) */ cut?: number; /** its hits mark (Hunter's Mark) this many more */ mark?: number };
  /** Its hits are centred where the caster is now, not where it was cast (Tempest Ride: she rides it). */
  follow?: boolean;
  /** Dash carries the first confirmed target along on the blade. */
  carry?: boolean;
  /** fuseMs: stepping on it arms it (hits[0] at once), then it explodes after fuseMs (hits[1] on everyone in it). */
  trap?: { radius: number; lifeMs: number; fuseMs?: number };
  armor?: [number, number]; // elapsed window (ms from cast) with armor
  /** Armor against shots only (projectiles), from the cast's start to [1] ms: a melee blow still lands (a shield charge). */
  shotArmor?: [number, number];
  /** Counter stance: its window (ms); where he reappears: `behind` px past the attacker (falls back to a `sidestep`). */
  counter?: { window: number; sidestep: number; behind?: number };
  /** Tags of skills this one may cancel into on a confirmed hit. */
  cancelOnHit: string[];
  tags: string[];
  endsCombo?: boolean;
  /** Visual: telegraph shown to everyone during startup. */
  telegraph?: 'circle' | 'cone' | 'line' | 'trajectory' | 'ground';
  pvpMultiplier: number;
  /** Arena: damage factor of its hits (light juggle tools hit softer so a long air string fits the gauges). */
  arenaDmg?: number;
  /** Arena: height factor of its launches (DFO pace: the foe juggled low, in reach of the next cut). */
  arenaLaunch?: number;
  pveMultiplier: number;
  description: string;
  unlockLevel: number;
  /** Skill points: another skill (active or passive, by id) it needs at a level before it can be learned. */
  requires?: { id: string; level: number };
  relations: string[];
  /** A template only (not built yet): listed in the skill book and on the skill bar as "coming soon", cannot be used. */
  wip?: boolean;
  /** The fighting style whose kit it belongs to (Styles.ts); none: the class's own kit, its first style. */
  style?: string;
  /** A style mechanic it feeds (StyleMechanics): its landed hit — a counter: its catch — earns the Siege Warden a gate
   *  charge / the Radiant Duelist a facet. */
  earns?: 'gate' | 'facets';
  /** A style mechanic it spends at its start (StyleMechanics): the Sailwright's Tack (Up / Down held: a new angle), the
   *  Duelist's facets (All In's stake: `stakes`), the Warden's gate charge (its `charged` hits instead). */
  spends?: 'tack' | 'facets' | 'gate';
  /** A gate charge spent: these hits instead of `hits` (the Warden's better effect). */
  charged?: HitEvent[];
  /** All In's stakes by the facets staked (0–3): its thrust's reach, and what a hit in the outer quarter of it does — the
   *  payoff (none past `tip`: the plain thrust). */
  stakes?: { length: number; tip: Reaction; dmg?: number }[];
}

export const PVP_MULT = 0.7;

/** The fight's one pace (David 2 Nov: "the skills run very fast"): every class skill plays PACE× its kit's wind-up, strike,
 *  hit spacing and recovery (FinalKit.arenaTimeScale), and the combat reactions keep in step (Combat: hit-stun, the juggle's
 *  hang, holds, floor time — the foe slowed alike, so every combo links as before). Walking, running and jumping keep their
 *  speed. The same in the open game and in PvP. */
export const PACE = 1.35;
