export const passiveIconUrl = (p: PassiveSkill) => `assets/final/skills/${p.cls}/${p.id}/icon.png`;
export const passivesFor = (cls: string, job?: number) => PASSIVES.filter((p) => p.cls === cls && (job === undefined || p.job === job));

export interface PassiveStats {
  dmg: number; critAdd: number; critDmgAdd: number; takenMul: number; hpMul: number; moveMul: number; jumpMul: number;
  kbResist: number; ccResist: number; regen: boolean; fa: { chance: number; mul: number } | null; orbs: boolean; chanceAttack: number; airLeap: boolean;
  /** Archer: chance to dodge a hit entirely, projectile range multiplier, attack-speed multiplier (startup / recovery divided by it). */
  evade: number; rangeMul: number; atkSpeed: number;
  /** Book Mage rules (the mage spec). */
  mage: { levitate: boolean; weave: boolean; attune: boolean; coldBlood: boolean; barrier: boolean; conductor: boolean; blinkRune: boolean; recovery: boolean; shatter: boolean; grand: boolean; timeLord: boolean; sigil: boolean };
  /** Gambler rules (the gambler spec). */
  gamble: { shortFuse: boolean; streak: boolean; counting: boolean; cheatDeath: boolean; stacked: boolean; joker: boolean };
  cdMul: number;
}

export const NO_PASSIVES: PassiveStats = { dmg: 1, critAdd: 0, critDmgAdd: 0, takenMul: 1, hpMul: 1, moveMul: 1, jumpMul: 1, kbResist: 0, ccResist: 0, regen: false, fa: null, orbs: false, chanceAttack: 1, airLeap: false, evade: 0, rangeMul: 1, atkSpeed: 1, cdMul: 1,
  mage: { levitate: false, weave: false, attune: false, coldBlood: false, barrier: false, conductor: false, blinkRune: false, recovery: false, shatter: false, grand: false, timeLord: false, sigil: false },
  gamble: { shortFuse: false, streak: false, counting: false, cheatDeath: false, stacked: false, joker: false } };

/** Passives owned at this level (all = arena / QA: every job open). */
export function ownedPassives(cls: string, level: number, all: boolean): Set<string> {
  const jobs = jobsFor(cls);
  return new Set(passivesFor(cls).filter((p) => !p.wip && (all || level >= (jobs[p.job]?.level ?? Infinity))).map((p) => p.id));
}

export function passiveStats(owned: Set<string>): PassiveStats {
  const s: PassiveStats = { ...NO_PASSIVES, mage: { ...NO_PASSIVES.mage }, gamble: { ...NO_PASSIVES.gamble } };
  const has = (id: string) => owned.has(id);
  if (has('war_leap')) s.airLeap = true;
  if (has('warrior_mastery')) { s.moveMul *= 1.1; s.jumpMul *= 1.1; s.hpMul += 0.2; s.kbResist = 0.3; }
  if (has('iron_body')) { s.takenMul *= 0.9; s.hpMul += 0.1; }
  if (has('sword_mastery')) { s.dmg *= 1.1; s.critAdd += 0.05; }
  if (has('final_attack')) s.fa = { chance: 0.25, mul: 0.35 };
  if (has('combo_force')) s.orbs = true;
  if (has('self_recovery')) s.regen = true;
  if (has('endure')) s.ccResist = 0.3;
  if (has('chance_attack')) s.chanceAttack = 1.2;
  if (has('iron_oath')) s.hpMul += 0.15;
  if (has('legacy_banner')) { s.dmg *= 1.05; s.takenMul *= 0.95; }
  if (has('power_stance')) s.kbResist = 0.7;
  if (has('combat_mastery')) { s.critAdd += 0.1; s.critDmgAdd += 0.2; }
  if (has('advanced_final_attack')) s.fa = { chance: 0.45, mul: 0.55 };
  // Archer
  if (has('wind_leap')) s.airLeap = true;
  if (has('bow_mastery')) { s.dmg *= 1.1; s.critAdd += 0.05; }
  if (has('light_body')) { s.moveMul *= 1.1; s.evade += 0.05; }
  if (has('extra_shot')) s.fa = { chance: 0.25, mul: 0.35 };
  if (has('keen_eye')) s.critAdd += 0.1;
  if (has('physical_training')) s.hpMul += 0.2;
  if (has('evasion')) s.evade += 0.15;
  if (has('focus')) s.critDmgAdd += 0.2;
  if (has('ranger_mastery')) { s.dmg *= 1.1; s.atkSpeed *= 1.1; }
  if (has('steadfast')) s.kbResist = 0.6;
  if (has('supreme_mastery')) { s.dmg *= 1.15; s.critDmgAdd += 0.1; }
  if (has('eagle_eyes')) s.rangeMul = 1.2;
  // Samurai
  if (has('shinsoku')) s.airLeap = true;
  if (has('katana_mastery')) { s.dmg *= 1.1; s.critAdd += 0.05; s.atkSpeed *= 1.1; } // (Quick Draw's speed, now always on)
  if (has('bushido_body')) { s.hpMul += 0.2; s.moveMul *= 1.1; }
  if (has('willow_dodge')) s.evade += 0.1;
  if (has('final_cut')) s.fa = { chance: 0.25, mul: 0.35 };
  if (has('steel_spirit')) { s.takenMul *= 0.9; s.hpMul += 0.1; }
  if (has('shogun_mastery')) { s.dmg *= 1.1; s.atkSpeed *= 1.1; }
  if (has('unshaken')) s.kbResist = Math.max(s.kbResist, 0.6);
  if (has('iron_will')) s.ccResist = Math.max(s.ccResist, 0.3);
  if (has('way_of_the_sword')) { s.critAdd += 0.1; s.critDmgAdd += 0.2; }
  if (has('sword_saint')) { s.dmg *= 1.15; s.critDmgAdd += 0.1; }
  if (has('advanced_final_cut')) s.fa = { chance: 0.45, mul: 0.55 };
  // Gambler
  const G = s.gamble;
  if (has('card_step')) s.airLeap = true;
  if (has('kinetic_mastery')) { s.dmg *= 1.1; s.critAdd += 0.05; }
  if (has('street_smarts')) { s.hpMul += 0.15; s.moveMul *= 1.1; }
  if (has('short_fuse')) G.shortFuse = true;
  if (has('extra_card')) s.fa = { chance: 0.25, mul: 0.35 };
  if (has('lucky_streak')) G.streak = true;
  if (has('card_counting')) G.counting = true;
  if (has('cheat_death')) G.cheatDeath = true;
  if (has('steady_hands')) s.kbResist = Math.max(s.kbResist, 0.6);
  if (has('high_stakes')) { s.critAdd += 0.1; s.critDmgAdd += 0.2; }
  if (has('stacked_deck')) G.stacked = true;
  if (has('ace_of_fate')) { s.dmg *= 1.15; s.critDmgAdd += 0.1; G.joker = true; }
  // Book Mage
  const M = s.mage;
  if (has('levitate')) M.levitate = true;
  if (has('spell_weave')) M.weave = true;
  if (has('arcane_mind')) { s.hpMul += 0.15; s.ccResist = Math.max(s.ccResist, 0.2); }
  if (has('attunement')) M.attune = true;
  if (has('cold_blood')) M.coldBlood = true;
  if (has('chrono_haste')) { s.moveMul *= 1.1; s.atkSpeed *= 1.1; s.cdMul *= 0.9; }
  if (has('chrono_sigil')) M.sigil = true;
  if (has('mana_barrier')) M.barrier = true;
  if (has('conductor')) M.conductor = true;
  if (has('blink_mastery')) M.blinkRune = true;
  if (has('arcane_recovery')) M.recovery = true;
  if (has('shatter_mastery')) M.shatter = true;
  if (has('grand_weave')) M.grand = true;
  if (has('time_lord')) { M.timeLord = true; s.cdMul *= 0.85; }
  return s;
}

